function calculateCombinationValue(e,t,n){const a=new Date;switch(e.type){case"sum":return calculateSum(e.eventIds,t,n,a);case"difference":return calculateDifference(e.eventIds,t,n,a);case"ratio":return calculateRatio(e.eventIds,t,n,a);case"balance":return calculateBalanceDiff(e.groupA,e.groupB,t,n,a);case"duration":return calculateDurationBetween(e.eventIds,t,n);default:return 0}}function calculateSum(e,t,n,a){a=a||new Date;let i=0;for(const o of e){const e=t.find(e=>e.id===o);e&&(i+=calculateAge(new Date(e.date),a,n))}return i}function calculateDifference(e,t,n,a){if(e.length<2)return 0;a=a||new Date;const i=t.find(t=>t.id===e[0]),o=t.find(t=>t.id===e[1]);if(!i||!o)return 0;return calculateAge(new Date(i.date),a,n)-calculateAge(new Date(o.date),a,n)}function calculateRatio(e,t,n,a){if(e.length<2)return 0;a=a||new Date;const i=t.find(t=>t.id===e[0]),o=t.find(t=>t.id===e[1]);if(!i||!o)return 0;const c=calculateAge(new Date(i.date),a,n),s=calculateAge(new Date(o.date),a,n);return 0===s?1/0:c/s}function calculateBalanceDiff(e,t,n,a,i){return calculateSum(e,n,a,i=i||new Date)-calculateSum(t,n,a,i)}function calculateDurationBetween(e,t,n){const a=e.map(e=>t.find(t=>t.id===e)).filter(e=>e).map(e=>new Date(e.date));if(a.length<2)return 0;const i=a.sort((e,t)=>e.getTime()-t.getTime()),o=i[0],c=i[i.length-1];return calculateAge(o,c,n)}function getCombinationStats(e,t){const n={};for(const[a,i]of Object.entries(TIME_UNITS)){const o=calculateCombinationValue(e,t,a);n[a]={value:o,formatted:formatCombinationValue(o,e.type),name:i.name,plural:i.plural}}return n}function formatCombinationValue(e,t){return"ratio"===t?e.toFixed(3):Math.floor(e).toLocaleString()}function findSumMilestones(e,t,n,a,i){n=n||30,a=a||365,i=i||DEFAULT_SETTINGS;const o=[],c=new Date,s=c.getTime()+24*a*60*60*1e3,l=e.eventIds.length;if(0===l)return[];for(const n of Object.keys(TIME_UNITS)){const a=TIME_UNITS[n],r=calculateSum(e.eventIds,t,n,c),u=getSpecialNumbersUpTo(a.maxReasonable*l,i);for(const e of u)if(e>r){const t=(e-r)/l;let u;if("months"===n)u=addCalendarMonths(c,Math.ceil(t));else if("years"===n)u=addCalendarMonths(c,Math.ceil(12*t));else{const e=t*a.msMultiplier;u=new Date(c.getTime()+e)}if(u.getTime()<=s){const t=isSpecialNumber(e,i);o.push({value:e,unit:n,unitName:a.name,date:u,type:t.type,description:`Combined: ${t.description}`,timeUntil:u.getTime()-c.getTime()})}}}return o.sort((e,t)=>e.date.getTime()-t.date.getTime()).slice(0,n)}function findDifferenceMilestones(e,t,n,a,i){n=n||30,a=a||365,i=i||DEFAULT_SETTINGS;const o=[],c=new Date;for(const n of Object.keys(TIME_UNITS)){const a=TIME_UNITS[n],s=calculateDifference(e.eventIds,t,n,c);if(s>0){const e=isSpecialNumber(Math.floor(s),i);"special"!==e.type&&o.push({value:Math.floor(s),unit:n,unitName:a.name,date:c,type:e.type,description:`Age difference: ${e.description}`,timeUntil:0,isStatic:!0})}}return o.slice(0,n)}function findRatioMilestones(e,t,n,a,i){n=n||20,a=a||1825;const o=[],c=new Date;if(e.eventIds.length<2)return[];const s=t.find(t=>t.id===e.eventIds[0]),l=t.find(t=>t.id===e.eventIds[1]);if(!s||!l)return[];const r=new Date(s.date),u=new Date(l.date),d=[2,3,4,5,1.5,2.5,3.5];for(const e of["days","years"]){const t=TIME_UNITS[e];for(const n of d){const i=calculateAge(r,c,"days"),d=calculateAge(u,c,"days");if(1===n)continue;const f=(n*d-i)/(1-n);if(f>0){const i=f*TIME_UNITS.days.msMultiplier,r=new Date(c.getTime()+i);r.getTime()<=c.getTime()+24*a*60*60*1e3&&o.push({value:n,unit:e,unitName:t.name,date:r,type:"ratio",description:`${s.name} will be ${n}x ${l.name}'s age`,timeUntil:r.getTime()-c.getTime()})}}}return o.sort((e,t)=>e.date.getTime()-t.date.getTime()).slice(0,n)}function findBalanceMilestones(e,t,n,a,i){n=n||20,a=a||3650;const o=[],c=new Date;if(!e.groupA||!e.groupB)return[];const s=e.groupA.length,l=e.groupB.length;if(0===s||0===l)return[];for(const n of["days","weeks","years"]){const i=TIME_UNITS[n],r=calculateSum(e.groupA,t,n,c),u=calculateSum(e.groupB,t,n,c);if(s===l){r===u&&o.push({value:r,unit:n,unitName:i.name,date:c,type:"balance",description:`Groups are balanced at ${r.toLocaleString()} ${i.plural}!`,timeUntil:0,isBalance:!0});continue}const d=(u-r)/(s-l);if(d>0){const e=d*i.msMultiplier,t=new Date(c.getTime()+e);if(t.getTime()<=c.getTime()+24*a*60*60*1e3){const e=r+s*d;o.push({value:Math.round(e),unit:n,unitName:i.name,date:t,type:"balance",description:`Balance point: both groups at ${Math.round(e).toLocaleString()} ${i.plural}`,timeUntil:t.getTime()-c.getTime(),isBalance:!0})}}}return o.sort((e,t)=>e.date.getTime()-t.date.getTime()).slice(0,n)}function findDurationBetweenMilestones(e,t,n,a){const i=[];for(const n of Object.keys(TIME_UNITS)){const o=calculateDurationBetween(e.eventIds,t,n);if(o>0){const e=isSpecialNumber(o,a),t=TIME_UNITS[n];i.push({value:o,unit:n,unitName:t.name,date:new Date,type:e.type,description:`Duration: ${e.description}`,timeUntil:0,isStatic:!0})}}return i.slice(0,n||20)}function findCombinationMilestones(e,t,n,a,i){switch(e.type){case"sum":return findSumMilestones(e,t,n,a,i);case"difference":return findDifferenceMilestones(e,t,n,a,i);case"ratio":return findRatioMilestones(e,t,n,a,i);case"balance":return findBalanceMilestones(e,t,n,a,i);case"duration":return findDurationBetweenMilestones(e,t,n,i);default:return[]}}function findInterestingFindings(e,t,n){const a=[],i=new Date;if("sum"===e.type){const n=calculateSum(e.eventIds,t,"years",i),o=10*Math.ceil(n/10),c=e.eventIds.length;if(o>n&&o<=n+10){const e=365.25*((o-n)/c);e<365&&a.push({text:`Combined age will reach ${o} years in about ${Math.ceil(e)} days!`,type:"milestone"})}const s=calculateSum(e.eventIds,t,"seconds",i),l=1e9*Math.ceil(s/1e9);if(l-s<1e8*c){const e=(l-s)/c/86400;a.push({text:`Combined age will reach ${(l/1e9).toFixed(0)} billion seconds in about ${Math.ceil(e)} days!`,type:"milestone"})}}if("ratio"===e.type){const n=calculateRatio(e.eventIds,t,"years",i);n>1.9&&n<2.1&&a.push({text:"The first person is almost exactly twice as old as the second!",type:"interesting"}),Math.abs(n-Math.round(n))<.05&&n>1&&a.push({text:`Age ratio is very close to exactly ${Math.round(n)}:1`,type:"interesting"})}if("balance"===e.type){const n=calculateBalanceDiff(e.groupA,e.groupB,t,"years",i);Math.abs(n)<1&&a.push({text:"The groups are almost perfectly balanced in age!",type:"balance"})}return a}function suggestCombinations(e){const t=[],n=e.filter(e=>"birth"===e.type);if(n.length>=2&&t.push({name:"Family Total Age",type:"sum",eventIds:n.map(e=>e.id),description:`Track the combined age of ${n.length} family members`}),n.length>=2){const e=[...n].sort((e,t)=>new Date(e.date)-new Date(t.date));for(let n=0;n<e.length-1;n++){const a=e[n],i=e[e.length-1];calculateAge(new Date(a.date),new Date(i.date),"years")>=18&&t.push({name:`${a.person||a.name} vs ${i.person||i.name} Ratio`,type:"ratio",eventIds:[a.id,i.id],description:"Track when one becomes 2x, 3x the age of the other"})}}if(n.length>=3){const e=[...n].sort((e,t)=>new Date(e.date)-new Date(t.date)),a=e.slice(0,2),i=e.slice(2);i.length>0&&t.push({name:"Parents vs Kids Balance",type:"balance",groupA:a.map(e=>e.id),groupB:i.map(e=>e.id),description:"Find when kids' combined age equals parents' combined age"})}return t}window.calculateCombinationValue=calculateCombinationValue,window.getCombinationStats=getCombinationStats,window.findCombinationMilestones=findCombinationMilestones,window.findInterestingFindings=findInterestingFindings,window.suggestCombinations=suggestCombinations,window.calculateSum=calculateSum,window.calculateDifference=calculateDifference,window.calculateRatio=calculateRatio,window.calculateBalanceDiff=calculateBalanceDiff;